% mathsmap-diagram-colours {"version":1,"kind":"geometry","base":[],"semantic":[],"reference":"source page 69 p69-q10-c-answer-diagram"}
\begin{tikzpicture}[x=1cm,y=1cm,every node/.style={font=\fontsize{10}{12}\selectfont,text=black}]
\special{dvisvgm:raw <metadata data-graph-strokes="1"/>}
\pgfmathsetmacro{\longside}{3*sqrt(3)+sqrt(7)}
\pgfmathsetmacro{\shortside}{3*sqrt(3)-sqrt(7)}
\pgfmathsetmacro{\tilt}{atan((\longside*cos(30)-6)/(\longside*sin(30)))}
\coordinate (A) at (0,0);
\coordinate (B) at ({6*cos(\tilt)},{-6*sin(\tilt)});
\coordinate (C) at ({\longside*cos(\tilt+30)},{-\longside*sin(\tilt+30)});
\coordinate (D) at ({\shortside*cos(\tilt+30)},{-\shortside*sin(\tilt+30)});
\draw[black,line width=0.8pt] (A)--(B)--(C)--cycle;
\draw[black,line width=0.8pt] (B)--(D);
\node[above left] at (A) {$A$};
\node[above right] at (B) {$B$};
\node[right=3mm] at (C) {$C$};
\node[above right,xshift=2mm,yshift=2mm] at (D) {$C$};
\path (A)--(B) node[midway,above] {$6$};
\path (B)--(C) node[midway,right] {$4$};
\coordinate (AS) at ({0.7*cos(\tilt+120)},{-0.7*sin(\tilt+120)});
\coordinate (DS) at ({\shortside*cos(\tilt+30)+0.7*cos(\tilt+120)},{-\shortside*sin(\tilt+30)-0.7*sin(\tilt+120)});
\coordinate (AL) at ({1.65*cos(\tilt+120)},{-1.65*sin(\tilt+120)});
\coordinate (CL) at ({\longside*cos(\tilt+30)+1.65*cos(\tilt+120)},{-\longside*sin(\tilt+30)-1.65*sin(\tilt+120)});
\draw[black,<->,>=stealth,line width=0.4pt] (AS)--(DS) node[midway,sloped,below] {$3\sqrt{3}-\sqrt{7}$};
\draw[black,<->,>=stealth,line width=0.4pt] (AL)--(CL) node[midway,sloped,below] {$3\sqrt{3}+\sqrt{7}$};
\end{tikzpicture}
